#include <bits/stdc++.h>using namespace std; using pii = pair<int,int>; void solve() {    int n, k, p, m;    cin >> n >> k >> p >> m;    vector<int> a(n);    for (int i = 0; i < n; i++) cin >> a[i];     p--;    multiset<pii> ms;    deque<pii> dq;     for (int i = 0; i < n; i++) {        pii card = {i == p ? 0 : 1, a[i]};        if (i < k) ms.insert(card);        else dq.push_back(card);    }     int ans = 0;     while (!ms.empty()) {        auto it = ms.begin();        pii top = *it;        ms.erase(it);         if (m < top.second) break;        m -= top.second;        if (top.first == 0) ans++;         dq.push_back(top);         if (!dq.empty()) {            ms.insert(dq.front());            dq.pop_front();        }    }     cout << ans << endl;} int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) solve();     return 0;}